 ('analysis','Executed source grain, joins and deduplication audit',base+'research/raw/tender-portal-audit/analysis.json','ICIP source audit',None,'Exact SQL, query rows and sourceHashes in analysis.json; normalization recipe in derivation-manifest.json','analytic'),
 ('followup','Strict lexical, chronology and status controls',base+'research/raw/tender-portal-audit/followup.json','ICIP source audit',None,'Exact query IDs, SQL and bounded populations; followup.py does not mutate originals','analytic'),
 ('semantics','Award closing-field semantics in exact listing-only pairs',base+'research/raw/tender-portal-audit/closing-field-semantics.json','ICIP source audit',None,'field_equality, by_buyer, by_year; semantic_probe.py','analytic'),
 ('linkage','Separate detail-reference-fallback linkage audit',base+'research/raw/tender-portal-audit/linkage-v2.json','ICIP source audit',None,'reference_agreement, fallback_join_cardinality, closing_field_semantics; independently versioned linkage_v2.py','analytic'),
 ('numeric','Independent raw amount lexeme review',base+'docs/tender-investigation/amount-lexemes.json','Independent ICIP data reviewer',None,'central_nonplain_amounts; original amount strings only; no contact or winner data','analytic'),
