compact={'status':{'state':'complete','asOf':'2026-10-06','scope':'Corpus-level source and linkage audit; findings do not describe an individual buyer.','recordCount':len(records),'limitations':['Derived from publisher-hash-verified scraped records; source correctness remains separately verifiable.','Candidate links, nominal award values and short windows do not establish payment, delivery or wrongdoing.']},'findings':findings,'slice':{'sources':sources,'entities':[],'relationships':[],'records':records,'localities':[]},'inputHashes':{name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest() for name in paths}}
output=REPO/'src/data/procurement-audit.json'
